{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain off-white background, with dense, shaggy brown fur covering most of its body. Its overall build, head shape, and limbs resemble a bear, with a stout torso, thick neck, and four sturdy legs ending in clawed paws. Integrated into the fur are several glossy, hard, dark reddish-brown to black structures resembling the exoskeleton of a rhinoceros beetle: a single large curved horn on the forehead, a smooth shield-like plate over the shoulders and chest, and two oval, ridged, wing-cover-like shells on the mid-back and on the outer hindquarter. Two rows of small oval holes with dark rims run along the side of the torso through lighter fur, and dark segmented bands encircle each leg near the joints. The animal stands with all four feet on the ground, casting a faint shadow.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with a long blunt muzzle, black nose, small brown eyes, and light tan fur around the muzzle and cheeks, facing to the right",
      "where": "at the front of the body, attached to the thick neck"
    },
    {
      "part": "horns",
      "looks_like": "single large, glossy black, smooth, sharply curved horn with a small notch on the inner curve, tapering to a point",
      "where": "arising from the center of the forehead between the ears, curving up and backward"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears, same brown fur as the head",
      "where": "on top of the head, one on each side behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred, columnar legs with dark brown, glossy, segmented chitinous bands encircling the upper and lower joints",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad, furry paws each bearing five long, curved, pale claws",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very short, small, rounded tuft of brown fur",
      "where": "at the extreme rear of the body, just above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "two large, oval, highly glossy, dark reddish-brown, longitudinally ridged shells with a central seam, resembling beetle elytra",
      "where": "one covering the mid-back, one covering the outer side of the right hindquarter/hip"
    },
    {
      "part": "plates",
      "looks_like": "large, smooth, glossy dark brown to black shield-like plate with a pointed dorsal peak and irregular spiky lower edge, plus smaller spiky plates under the throat",
      "where": "covering the shoulders, upper back, and sides of the neck and chest"
    },
    {
      "part": "markings",
      "looks_like": "two horizontal rows of small, oval, dark-rimmed holes resembling spiracles, set in lighter tan fur; about seven holes in the upper row and eight in the lower row",
      "where": "along the lateral side of the torso, between the front and hind legs, below the back shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
